using System;
using System.Collections.Generic;

namespace _3D_Chart_Graph
{
	public class BuiltinEcu
	{
		public string Name;
		public string Resource;
		public int Cols;
		public int Rows;
		public float Kon;
		public float Lm;
		public int O2Mask;
		public int O2cMask;
		public int ImmoMask;
		public string Addr;

		public Dictionary<string, int> ToDict()
		{
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			foreach (string pair in Addr.Split(';'))
			{
				string[] kv = pair.Split('=');
				if (kv.Length == 2)
				{
					dictionary[kv[0]] = int.Parse(kv[1]);
				}
			}
			foreach (string key in EcuLayoutTools.AllAddrFields)
			{
				if (!dictionary.ContainsKey(key))
				{
					dictionary[key] = 0;
				}
			}
			return dictionary;
		}
	}

